-- Browser types
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.window_rule({
    match = {
        class = "((google-)?[cC]hrom(e|ium)|[bB]rave-browser|[mM]icrosoft-edge|Vivaldi-stable|helium)",
    },
    tag = "+chromium-based-browser",
})

hl.window_rule({
    match = {
        class = "([fF]irefox|zen|librewolf)",
    },
    tag = "+firefox-based-browser",
})

-- Force chromium-based browsers into a tile to deal with --app bug
hl.window_rule({
    match = {
        tag = "chromium-based-browser",
    },
    float = false,
})

-- Only a subtle opacity change, but not for video sites
hl.window_rule({
    match = {
        tag = "chromium-based-browser",
    },
    opacity = "1 0.97",
})

hl.window_rule({
    match = {
        tag = "firefox-based-browser",
    },
    opacity = "1 0.97",
})

-- Video sites stay opaque (dynamic title matching)
hl.window_rule({
    match = {
        title = "(YouTube|Twitch|Netflix|Prime Video|Disney\\+|Vimeo|Plex|HBO|Hulu|Crunchyroll)",
    },
    opacity = "1.0 1.0",
})

